CREATE TABLE semio_cad_document (id INTEGER PRIMARY KEY, schema TEXT NOT NULL);
CREATE TABLE semio_cad_layer (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES semio_cad_document(id), ordinal INTEGER NOT NULL CHECK (ordinal >= 0), name TEXT NOT NULL, color_index INTEGER NOT NULL CHECK (color_index BETWEEN -2147483648 AND 2147483647), line_type TEXT NOT NULL, visible INTEGER NOT NULL CHECK (visible IN (0,1)));
CREATE TABLE semio_cad_block (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES semio_cad_document(id), ordinal INTEGER NOT NULL CHECK (ordinal >= 0), name TEXT NOT NULL, base_x REAL, base_y REAL, base_x_ieee754_bits INTEGER, base_x_numeric_class TEXT, base_y_ieee754_bits INTEGER, base_y_numeric_class TEXT);
CREATE TABLE semio_cad_entity (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES semio_cad_document(id), block_id INTEGER REFERENCES semio_cad_block(id), ordinal INTEGER NOT NULL CHECK (ordinal >= 0), handle TEXT NOT NULL, layer_id INTEGER NOT NULL REFERENCES semio_cad_layer(id), kind TEXT NOT NULL CHECK (kind IN ('line','arc','circle','ellipse','polyline','text','insert','solid','dimension')));
CREATE TABLE semio_cad_line (id INTEGER PRIMARY KEY REFERENCES semio_cad_entity(id), a_x REAL, a_y REAL, b_x REAL, b_y REAL, a_x_ieee754_bits INTEGER, a_x_numeric_class TEXT, a_y_ieee754_bits INTEGER, a_y_numeric_class TEXT, b_x_ieee754_bits INTEGER, b_x_numeric_class TEXT, b_y_ieee754_bits INTEGER, b_y_numeric_class TEXT);
CREATE TABLE semio_cad_arc (id INTEGER PRIMARY KEY REFERENCES semio_cad_entity(id), center_x REAL, center_y REAL, radius REAL, start_angle REAL, end_angle REAL, center_x_ieee754_bits INTEGER, center_x_numeric_class TEXT, center_y_ieee754_bits INTEGER, center_y_numeric_class TEXT, radius_ieee754_bits INTEGER, radius_numeric_class TEXT, start_angle_ieee754_bits INTEGER, start_angle_numeric_class TEXT, end_angle_ieee754_bits INTEGER, end_angle_numeric_class TEXT);
CREATE TABLE semio_cad_circle (id INTEGER PRIMARY KEY REFERENCES semio_cad_entity(id), center_x REAL, center_y REAL, radius REAL, center_x_ieee754_bits INTEGER, center_x_numeric_class TEXT, center_y_ieee754_bits INTEGER, center_y_numeric_class TEXT, radius_ieee754_bits INTEGER, radius_numeric_class TEXT);
CREATE TABLE semio_cad_ellipse (id INTEGER PRIMARY KEY REFERENCES semio_cad_entity(id), center_x REAL, center_y REAL, major_axis_x REAL, major_axis_y REAL, ratio REAL, start_parameter REAL, end_parameter REAL, center_x_ieee754_bits INTEGER, center_x_numeric_class TEXT, center_y_ieee754_bits INTEGER, center_y_numeric_class TEXT, major_axis_x_ieee754_bits INTEGER, major_axis_x_numeric_class TEXT, major_axis_y_ieee754_bits INTEGER, major_axis_y_numeric_class TEXT, ratio_ieee754_bits INTEGER, ratio_numeric_class TEXT, start_parameter_ieee754_bits INTEGER, start_parameter_numeric_class TEXT, end_parameter_ieee754_bits INTEGER, end_parameter_numeric_class TEXT);
CREATE TABLE semio_cad_polyline (id INTEGER PRIMARY KEY REFERENCES semio_cad_entity(id), closed INTEGER NOT NULL CHECK (closed IN (0,1)));
CREATE TABLE semio_cad_polyline_vertex (id INTEGER PRIMARY KEY, polyline_id INTEGER NOT NULL REFERENCES semio_cad_polyline(id), ordinal INTEGER NOT NULL CHECK (ordinal >= 0), x REAL, y REAL, x_ieee754_bits INTEGER, x_numeric_class TEXT, y_ieee754_bits INTEGER, y_numeric_class TEXT);
CREATE TABLE semio_cad_text (id INTEGER PRIMARY KEY REFERENCES semio_cad_entity(id), position_x REAL, position_y REAL, height REAL, rotation REAL, content TEXT NOT NULL, position_x_ieee754_bits INTEGER, position_x_numeric_class TEXT, position_y_ieee754_bits INTEGER, position_y_numeric_class TEXT, height_ieee754_bits INTEGER, height_numeric_class TEXT, rotation_ieee754_bits INTEGER, rotation_numeric_class TEXT);
CREATE TABLE semio_cad_insert (id INTEGER PRIMARY KEY REFERENCES semio_cad_entity(id), target_block_id INTEGER NOT NULL REFERENCES semio_cad_block(id), insertion_x REAL, insertion_y REAL, scale_x REAL, scale_y REAL, rotation REAL, insertion_x_ieee754_bits INTEGER, insertion_x_numeric_class TEXT, insertion_y_ieee754_bits INTEGER, insertion_y_numeric_class TEXT, scale_x_ieee754_bits INTEGER, scale_x_numeric_class TEXT, scale_y_ieee754_bits INTEGER, scale_y_numeric_class TEXT, rotation_ieee754_bits INTEGER, rotation_numeric_class TEXT);
CREATE TABLE semio_cad_solid (id INTEGER PRIMARY KEY REFERENCES semio_cad_entity(id), p1_x REAL, p1_y REAL, p2_x REAL, p2_y REAL, p3_x REAL, p3_y REAL, p4_x REAL, p4_y REAL, p1_x_ieee754_bits INTEGER, p1_x_numeric_class TEXT, p1_y_ieee754_bits INTEGER, p1_y_numeric_class TEXT, p2_x_ieee754_bits INTEGER, p2_x_numeric_class TEXT, p2_y_ieee754_bits INTEGER, p2_y_numeric_class TEXT, p3_x_ieee754_bits INTEGER, p3_x_numeric_class TEXT, p3_y_ieee754_bits INTEGER, p3_y_numeric_class TEXT, p4_x_ieee754_bits INTEGER, p4_x_numeric_class TEXT, p4_y_ieee754_bits INTEGER, p4_y_numeric_class TEXT);
CREATE TABLE semio_cad_dimension (id INTEGER PRIMARY KEY REFERENCES semio_cad_entity(id), definition_x REAL, definition_y REAL, text_x REAL, text_y REAL, measurement REAL, text TEXT NOT NULL, definition_x_ieee754_bits INTEGER, definition_x_numeric_class TEXT, definition_y_ieee754_bits INTEGER, definition_y_numeric_class TEXT, text_x_ieee754_bits INTEGER, text_x_numeric_class TEXT, text_y_ieee754_bits INTEGER, text_y_numeric_class TEXT, measurement_ieee754_bits INTEGER, measurement_numeric_class TEXT);
